// Package: Microsoft.SemanticKernel --version 1.25+

using Microsoft.SemanticKernel;
using Microsoft.SemanticKernel.Process;
using Microsoft.Extensions.AI;

// Define process steps using [KernelFunction]
public class GetOrderStep
{
    [KernelFunction, Description("Get order details by ID.")]
    public Task<string> GetOrderAsync(string orderId, CancellationToken ct = default)
    {
        return Task.FromResult(orderId == "ABC123"
            ? "Order ABC123 | Status: Shipped | Items: 3"
            : "Order not found.");
    }
}

public class CheckDiscountStep
{
    [KernelFunction, Description("Check discount eligibility for an order.")]
    public Task<string> CheckDiscountAsync(string orderId, CancellationToken ct = default)
    {
        return Task.FromResult(orderId == "ABC123"
            ? "Eligible for 10% loyalty discount."
            : "Not eligible for discount.");
    }
}

public class ApplyDiscountStep
{
    [KernelFunction, Description("Apply a discount code to an order.")]
    public Task<string> ApplyDiscountAsync(string orderId, string discountCode, CancellationToken ct = default)
    {
        return Task.FromResult($"Discount {discountCode} applied to order {orderId}. New total: $135.00");
    }
}

// Build the process
var builder = Kernel.CreateBuilder()
    .AddOpenAIChatCompletion("gpt-4o", new OpenAIClient("your-api-key"));

var kernel = builder.Build();

var processBuilder = new ProcessBuilder("order_process");

processBuilder
    .AddStepFromType<GetOrderStep>("get_order")
    .AddStepFromType<CheckDiscountStep>("check_discount")
    .AddStepFromType<ApplyDiscountStep>("apply_discount");

processBuilder
    .OnEdgeEvent("get_order", "check_discount", (from, to, context) =>
    {
        // Only proceed to discount check if order was found
        return context.State.GetValue<string>("get_order.result")?.Contains("Shipped") == true;
    })
    .OnEdgeEvent("check_discount", "apply_discount", (from, to, context) =>
    {
        // Only apply discount if eligible
        return context.State.GetValue<string>("check_discount.result")?.Contains("Eligible") == true;
    });

var process = processBuilder.Build();
var processExecutor = kernel.Factory.CreateProcessExecutor(process);

// Run the process
var processInstance = processExecutor.CreateProcessInstance();
var result = await processExecutor.StartAsync(processInstance, cancellationToken);

Console.WriteLine($"Process completed: {result}");
// Expected output: Process completed: Discount LOYALTY10 applied to order ABC123. New total: $135.00
